[423]={["aftermath"]="Dalar remained unsure whether the limited samples would yield enough energy.",["atomIDs"]={"423:description:1-65","423:description:68-187","423:description:190-195","423:description:200-255","423:description:258-298","423:description:301-439","423:description:442-497","423:objective:1-86"},["endingAtomIDs"]={"423:completion:1-62","423:completion:64-111","423:completion:116-175"},["opening"]="Dalar's examination pointed to enchanted objects reinforcing Arugal's spells. Shackles carried by gluttons and darksouls would let him study that support directly.",["pending"]="{actor} intended to gather both kinds of shackles.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Dalar with both kinds of shackles.",["sourceHash"]="b7a2eb34ae461028d2fd30bc479542bb969acabffe92e47c9e7f4baca09a22ab",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
